CREATE TABLE IF NOT EXISTS "buildings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short code used on every statement, work order and utility invoice. Stable across renaming and resale.
	"building_code" VARCHAR(24) NOT NULL UNIQUE,
	-- Name staff and tenants use for the property.
	"name" VARCHAR(200) NOT NULL,
	-- Street address of the building.
	"address_line1" VARCHAR(200) NOT NULL,
	-- City, which with the region decides the tenancy law that applies.
	"city" VARCHAR(120) NOT NULL,
	-- State or province. Notice periods, deposit caps and eviction rules are all set here, so it is not merely a display field.
	"region" VARCHAR(120),
	-- Postal code.
	"postcode" VARCHAR(16),
	-- ISO 3166-1 alpha-2.
	"country_code" CHAR(2) NOT NULL,
	-- IANA zone. Rent due dates and notice deadlines are local calendar facts, and computing them in UTC produces off-by-one days at month ends.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Construction year, which drives inspection frequency in several jurisdictions.
	"year_built" SMALLINT,
	-- Unit count, cached for portfolio dashboards. The units table is the source of truth.
	"total_units" INTEGER NOT NULL DEFAULT 0,
	-- Shared floor area. One of the bases for apportioning a building-level utility bill across units.
	"common_area_sqm" NUMERIC(10,2),
	-- Property manager responsible. Text rather than a foreign key because this schema deliberately stops short of being a staff directory.
	"manager_name" VARCHAR(200),
	-- When the landlord took ownership. Charges and statements before this date belong to a previous owner.
	"acquired_on" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "buildings" IS 'A physical property containing units. Jurisdiction lives here rather than on the unit, because every legal rule that matters — notice periods, deposit caps, inspection rights — is set by where the building stands.';
COMMENT ON COLUMN "buildings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "buildings"."building_code" IS 'Short code used on every statement, work order and utility invoice. Stable across renaming and resale.';
COMMENT ON COLUMN "buildings"."name" IS 'Name staff and tenants use for the property.';
COMMENT ON COLUMN "buildings"."address_line1" IS 'Street address of the building.';
COMMENT ON COLUMN "buildings"."city" IS 'City, which with the region decides the tenancy law that applies.';
COMMENT ON COLUMN "buildings"."region" IS 'State or province. Notice periods, deposit caps and eviction rules are all set here, so it is not merely a display field.';
COMMENT ON COLUMN "buildings"."postcode" IS 'Postal code.';
COMMENT ON COLUMN "buildings"."country_code" IS 'ISO 3166-1 alpha-2.';
COMMENT ON COLUMN "buildings"."timezone" IS 'IANA zone. Rent due dates and notice deadlines are local calendar facts, and computing them in UTC produces off-by-one days at month ends.';
COMMENT ON COLUMN "buildings"."year_built" IS 'Construction year, which drives inspection frequency in several jurisdictions.';
COMMENT ON COLUMN "buildings"."total_units" IS 'Unit count, cached for portfolio dashboards. The units table is the source of truth.';
COMMENT ON COLUMN "buildings"."common_area_sqm" IS 'Shared floor area. One of the bases for apportioning a building-level utility bill across units.';
COMMENT ON COLUMN "buildings"."manager_name" IS 'Property manager responsible. Text rather than a foreign key because this schema deliberately stops short of being a staff directory.';
COMMENT ON COLUMN "buildings"."acquired_on" IS 'When the landlord took ownership. Charges and statements before this date belong to a previous owner.';

CREATE TABLE IF NOT EXISTS "units" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Building the unit sits in.
	"building_id" BIGINT NOT NULL,
	-- Door number or designation as used by residents and by the postal service.
	"unit_number" VARCHAR(24) NOT NULL,
	-- Floor level. Null for houses and for units where the concept does not apply.
	"floor" SMALLINT,
	-- Bedroom count, the primary listing attribute and a driver of the occupancy limit.
	"bedrooms" SMALLINT,
	-- Bathroom count, allowing halves.
	"bathrooms" NUMERIC(3,1),
	-- Internal area in square metres. The default basis for apportioning building utility costs, which is why it is worth capturing accurately.
	"floor_area_sqm" NUMERIC(10,2),
	-- Current asking rent in minor units. What the unit should earn, as opposed to what a sitting lease actually charges.
	"market_rent_minor" BIGINT,
	-- ISO 4217 currency for this unit. Held per unit because portfolios do cross borders.
	"currency_code" CHAR(3) NOT NULL,
	-- vacant | occupied | notice_given | renovating | off_market. Notice given is separate from occupied because it is the state that drives re-letting activity.
	"status" VARCHAR(24) NOT NULL DEFAULT 'vacant',
	-- Whether the unit is let furnished, which changes both the rent and the inventory taken at check-in.
	"is_furnished" BOOLEAN NOT NULL DEFAULT false,
	-- Allocated spaces, frequently charged separately and therefore relevant to charge generation.
	"parking_spaces" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "units" IS 'The lettable thing. Every financial event in the schema ultimately hangs off a unit, and vacancy is measured here — an empty unit still exists, still costs money, and still needs inspections.';
COMMENT ON COLUMN "units"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "units"."building_id" IS 'Building the unit sits in.';
COMMENT ON COLUMN "units"."unit_number" IS 'Door number or designation as used by residents and by the postal service.';
COMMENT ON COLUMN "units"."floor" IS 'Floor level. Null for houses and for units where the concept does not apply.';
COMMENT ON COLUMN "units"."bedrooms" IS 'Bedroom count, the primary listing attribute and a driver of the occupancy limit.';
COMMENT ON COLUMN "units"."bathrooms" IS 'Bathroom count, allowing halves.';
COMMENT ON COLUMN "units"."floor_area_sqm" IS 'Internal area in square metres. The default basis for apportioning building utility costs, which is why it is worth capturing accurately.';
COMMENT ON COLUMN "units"."market_rent_minor" IS 'Current asking rent in minor units. What the unit should earn, as opposed to what a sitting lease actually charges.';
COMMENT ON COLUMN "units"."currency_code" IS 'ISO 4217 currency for this unit. Held per unit because portfolios do cross borders.';
COMMENT ON COLUMN "units"."status" IS 'vacant | occupied | notice_given | renovating | off_market. Notice given is separate from occupied because it is the state that drives re-letting activity.';
COMMENT ON COLUMN "units"."is_furnished" IS 'Whether the unit is let furnished, which changes both the rent and the inventory taken at check-in.';
COMMENT ON COLUMN "units"."parking_spaces" IS 'Allocated spaces, frequently charged separately and therefore relevant to charge generation.';

CREATE UNIQUE INDEX "uq_units_building_number"
ON "units" ("building_id", "unit_number");
CREATE INDEX "idx_units_status_building"
ON "units" ("status", "building_id");

CREATE TABLE IF NOT EXISTS "tenants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Quotable reference kept across tenancies, so a returning tenant is recognisable and their payment history is not lost.
	"tenant_reference" VARCHAR(24) NOT NULL UNIQUE,
	-- Legal name as it appears on the lease and on identity documents.
	"full_name" VARCHAR(200) NOT NULL,
	-- Primary contact address for statements, notices and arrears reminders.
	"email" VARCHAR(320) NOT NULL,
	-- Contact number, also used for maintenance access arrangements.
	"phone" VARCHAR(32),
	-- Required by referencing agencies and for right-to-rent checks in some jurisdictions.
	"date_of_birth" DATE,
	-- Who to call if the unit is on fire and the tenant is not answering.
	"emergency_contact_name" VARCHAR(200),
	-- Emergency number.
	"emergency_contact_phone" VARCHAR(32),
	-- pending | passed | failed | waived. A lease should not commence against a failed screening, and waived records an explicit override rather than a missing check.
	"screening_status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- When referencing finished.
	"screening_completed_at" TIMESTAMPTZ,
	-- First time this person entered the system, usually as an applicant.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tenants" IS 'A person, not a tenancy. Keeping them separate is what lets a tenant hold two leases at once, move between units in the portfolio, and return years later with their history intact.';
COMMENT ON COLUMN "tenants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "tenants"."tenant_reference" IS 'Quotable reference kept across tenancies, so a returning tenant is recognisable and their payment history is not lost.';
COMMENT ON COLUMN "tenants"."full_name" IS 'Legal name as it appears on the lease and on identity documents.';
COMMENT ON COLUMN "tenants"."email" IS 'Primary contact address for statements, notices and arrears reminders.';
COMMENT ON COLUMN "tenants"."phone" IS 'Contact number, also used for maintenance access arrangements.';
COMMENT ON COLUMN "tenants"."date_of_birth" IS 'Required by referencing agencies and for right-to-rent checks in some jurisdictions.';
COMMENT ON COLUMN "tenants"."emergency_contact_name" IS 'Who to call if the unit is on fire and the tenant is not answering.';
COMMENT ON COLUMN "tenants"."emergency_contact_phone" IS 'Emergency number.';
COMMENT ON COLUMN "tenants"."screening_status" IS 'pending | passed | failed | waived. A lease should not commence against a failed screening, and waived records an explicit override rather than a missing check.';
COMMENT ON COLUMN "tenants"."screening_completed_at" IS 'When referencing finished.';
COMMENT ON COLUMN "tenants"."created_at" IS 'First time this person entered the system, usually as an applicant.';

CREATE TABLE IF NOT EXISTS "leases" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Unit being let.
	"unit_id" BIGINT NOT NULL,
	-- Reference printed on the agreement and quoted in every notice.
	"lease_reference" VARCHAR(32) NOT NULL UNIQUE,
	-- draft | active | expired | terminated | renewed. A renewal sets the old lease to renewed and points the new one back at it, so the chain is explicit.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- Previous lease this renews. Null for a first tenancy. A renewal is a new row because the rent, the term and often the signatories all change.
	"renewed_from_lease_id" BIGINT,
	-- First day of the tenancy. Charge generation starts here.
	"term_start" DATE NOT NULL,
	-- Last day of the fixed term. Null for a rolling or periodic tenancy, which is a genuinely open-ended state rather than a missing value.
	"term_end" DATE,
	-- Contracted rent per billing period, in minor units. Charge generation copies this figure rather than joining to it.
	"rent_amount_minor" BIGINT NOT NULL,
	-- ISO 4217 currency of the rent.
	"currency_code" CHAR(3) NOT NULL,
	-- weekly | fortnightly | monthly | quarterly. Decides how many charge rows a year of tenancy produces.
	"billing_period" VARCHAR(16) NOT NULL DEFAULT 'monthly',
	-- Day of the period the rent falls due. A number rather than a rule, because a tenancy starting on the 15th usually stays on the 15th.
	"rent_due_day" SMALLINT NOT NULL DEFAULT 1,
	-- Contracted deposit in minor units. The actual money held and its protection details live in security_deposits.
	"deposit_amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- Flat fee charged after the grace period. Zero where the jurisdiction forbids it, which is why it is data and not code.
	"late_fee_minor" BIGINT NOT NULL DEFAULT 0,
	-- Days after the due date before a charge counts as late. Arrears reporting starts after this window, not on the due date.
	"grace_period_days" SMALLINT NOT NULL DEFAULT 0,
	-- Notice required to end the tenancy. Copied from the jurisdiction rules at signing, because a later change of law does not rewrite a signed agreement.
	"notice_period_days" SMALLINT,
	-- When the last signature landed. Null on a draft, and the presence of this value is what permits charges to be generated.
	"signed_at" TIMESTAMPTZ,
	-- Early termination date, if any. Distinct from term_end, and it is what stops future charge generation.
	"terminated_on" DATE,
	-- tenant_notice | landlord_notice | mutual | breach | abandonment. Drives both the deposit process and the vacancy report.
	"termination_reason" VARCHAR(40),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "leases" IS 'The contract. It is versioned by renewal rather than edited: a rent increase at renewal creates a new lease pointing back at the old one, so the charges generated under each set of terms remain explicable.';
COMMENT ON COLUMN "leases"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "leases"."unit_id" IS 'Unit being let.';
COMMENT ON COLUMN "leases"."lease_reference" IS 'Reference printed on the agreement and quoted in every notice.';
COMMENT ON COLUMN "leases"."status" IS 'draft | active | expired | terminated | renewed. A renewal sets the old lease to renewed and points the new one back at it, so the chain is explicit.';
COMMENT ON COLUMN "leases"."renewed_from_lease_id" IS 'Previous lease this renews. Null for a first tenancy. A renewal is a new row because the rent, the term and often the signatories all change.';
COMMENT ON COLUMN "leases"."term_start" IS 'First day of the tenancy. Charge generation starts here.';
COMMENT ON COLUMN "leases"."term_end" IS 'Last day of the fixed term. Null for a rolling or periodic tenancy, which is a genuinely open-ended state rather than a missing value.';
COMMENT ON COLUMN "leases"."rent_amount_minor" IS 'Contracted rent per billing period, in minor units. Charge generation copies this figure rather than joining to it.';
COMMENT ON COLUMN "leases"."currency_code" IS 'ISO 4217 currency of the rent.';
COMMENT ON COLUMN "leases"."billing_period" IS 'weekly | fortnightly | monthly | quarterly. Decides how many charge rows a year of tenancy produces.';
COMMENT ON COLUMN "leases"."rent_due_day" IS 'Day of the period the rent falls due. A number rather than a rule, because a tenancy starting on the 15th usually stays on the 15th.';
COMMENT ON COLUMN "leases"."deposit_amount_minor" IS 'Contracted deposit in minor units. The actual money held and its protection details live in security_deposits.';
COMMENT ON COLUMN "leases"."late_fee_minor" IS 'Flat fee charged after the grace period. Zero where the jurisdiction forbids it, which is why it is data and not code.';
COMMENT ON COLUMN "leases"."grace_period_days" IS 'Days after the due date before a charge counts as late. Arrears reporting starts after this window, not on the due date.';
COMMENT ON COLUMN "leases"."notice_period_days" IS 'Notice required to end the tenancy. Copied from the jurisdiction rules at signing, because a later change of law does not rewrite a signed agreement.';
COMMENT ON COLUMN "leases"."signed_at" IS 'When the last signature landed. Null on a draft, and the presence of this value is what permits charges to be generated.';
COMMENT ON COLUMN "leases"."terminated_on" IS 'Early termination date, if any. Distinct from term_end, and it is what stops future charge generation.';
COMMENT ON COLUMN "leases"."termination_reason" IS 'tenant_notice | landlord_notice | mutual | breach | abandonment. Drives both the deposit process and the vacancy report.';

CREATE INDEX "idx_leases_unit_start"
ON "leases" ("unit_id", "term_start");
CREATE INDEX "idx_leases_status_end"
ON "leases" ("status", "term_end");

CREATE TABLE IF NOT EXISTS "lease_tenants" (
	-- Lease being held. Half of the composite key, which is why this table carries no surrogate id.
	"lease_id" BIGINT,
	-- Person on the agreement. Together with lease_id this prevents the same person being added twice.
	"tenant_id" BIGINT,
	-- tenant | co_tenant | guarantor | occupant. A guarantor is liable but does not live there; an occupant lives there but is not liable. The difference decides who gets chased for arrears.
	"role" VARCHAR(24) NOT NULL DEFAULT 'tenant',
	-- Share of liability in basis points, where the tenancy apportions it. Null means joint and several, which is the usual and much stronger position for the landlord.
	"liability_share_bps" INTEGER,
	-- Who receives statements and notices first. Exactly one per lease in practice.
	"is_primary_contact" BOOLEAN NOT NULL DEFAULT false,
	-- When this person joined the agreement. A mid-term addition is normal in shared housing.
	"added_on" DATE NOT NULL,
	-- When they left it. Null while on the lease. Kept rather than deleted, because liability for arrears incurred while they were on it does not end when they move out.
	"removed_on" DATE,
	PRIMARY KEY("lease_id", "tenant_id")
);

COMMENT ON TABLE "lease_tenants" IS 'Many-to-many between leases and people, with a role. Co-tenants, guarantors and permitted occupants are all different legal positions, and collapsing them into one tenant_id column on the lease loses exactly the distinction that matters when money is owed.';
COMMENT ON COLUMN "lease_tenants"."lease_id" IS 'Lease being held. Half of the composite key, which is why this table carries no surrogate id.';
COMMENT ON COLUMN "lease_tenants"."tenant_id" IS 'Person on the agreement. Together with lease_id this prevents the same person being added twice.';
COMMENT ON COLUMN "lease_tenants"."role" IS 'tenant | co_tenant | guarantor | occupant. A guarantor is liable but does not live there; an occupant lives there but is not liable. The difference decides who gets chased for arrears.';
COMMENT ON COLUMN "lease_tenants"."liability_share_bps" IS 'Share of liability in basis points, where the tenancy apportions it. Null means joint and several, which is the usual and much stronger position for the landlord.';
COMMENT ON COLUMN "lease_tenants"."is_primary_contact" IS 'Who receives statements and notices first. Exactly one per lease in practice.';
COMMENT ON COLUMN "lease_tenants"."added_on" IS 'When this person joined the agreement. A mid-term addition is normal in shared housing.';
COMMENT ON COLUMN "lease_tenants"."removed_on" IS 'When they left it. Null while on the lease. Kept rather than deleted, because liability for arrears incurred while they were on it does not end when they move out.';

CREATE TABLE IF NOT EXISTS "rent_charges" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lease the charge arises under.
	"lease_id" BIGINT NOT NULL,
	-- rent | utility | parking | late_fee | repair_recharge | adjustment | credit. One ledger for everything a tenant owes, because a statement shows them in one list and a payment settles them in one go.
	"charge_kind" VARCHAR(24) NOT NULL DEFAULT 'rent',
	-- First day of the period covered. Null for one-off charges such as a late fee.
	"period_start" DATE,
	-- Last day covered. Together with the start it is what makes a mid-period move-in pro-ratable.
	"period_end" DATE,
	-- Date the money is due. Arrears age from this date plus the grace period, and every reminder job reads it.
	"due_on" DATE NOT NULL,
	-- Amount charged in minor units. Positive for a charge, negative for a credit, so the balance is a single sum.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217 currency, copied from the lease so a later currency change cannot restate old charges.
	"currency_code" CHAR(3) NOT NULL,
	-- Total allocated against this charge, maintained by the allocation rows. The rows are authoritative; this exists so an arrears list is one scan.
	"paid_minor" BIGINT NOT NULL DEFAULT 0,
	-- open | part_paid | paid | waived | written_off. Waived and written off are different decisions with different accounting, and neither is a deletion.
	"status" VARCHAR(24) NOT NULL DEFAULT 'open',
	-- Whether the amount was reduced for a partial period. Flagged because a pro-rated first month is the single most disputed charge in residential letting.
	"is_prorated" BOOLEAN NOT NULL DEFAULT false,
	-- floor_area | occupancy | submeter | equal_share, for utility recharges. Records how a building bill was split, which is the first thing a tenant asks.
	"allocation_basis" VARCHAR(24),
	-- External document the charge derives from, such as a utility invoice number. Null for rent.
	"source_reference" VARCHAR(64),
	-- When the charge row was created by the billing run, which is normally well before it falls due.
	"generated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "rent_charges" IS 'A row per amount owed, generated in advance rather than computed on demand. This is the spine of the schema: rent is not a property of a lease, it is a sequence of obligations, each with its own due date, its own pro-ration and its own settlement.';
COMMENT ON COLUMN "rent_charges"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "rent_charges"."lease_id" IS 'Lease the charge arises under.';
COMMENT ON COLUMN "rent_charges"."charge_kind" IS 'rent | utility | parking | late_fee | repair_recharge | adjustment | credit. One ledger for everything a tenant owes, because a statement shows them in one list and a payment settles them in one go.';
COMMENT ON COLUMN "rent_charges"."period_start" IS 'First day of the period covered. Null for one-off charges such as a late fee.';
COMMENT ON COLUMN "rent_charges"."period_end" IS 'Last day covered. Together with the start it is what makes a mid-period move-in pro-ratable.';
COMMENT ON COLUMN "rent_charges"."due_on" IS 'Date the money is due. Arrears age from this date plus the grace period, and every reminder job reads it.';
COMMENT ON COLUMN "rent_charges"."amount_minor" IS 'Amount charged in minor units. Positive for a charge, negative for a credit, so the balance is a single sum.';
COMMENT ON COLUMN "rent_charges"."currency_code" IS 'ISO 4217 currency, copied from the lease so a later currency change cannot restate old charges.';
COMMENT ON COLUMN "rent_charges"."paid_minor" IS 'Total allocated against this charge, maintained by the allocation rows. The rows are authoritative; this exists so an arrears list is one scan.';
COMMENT ON COLUMN "rent_charges"."status" IS 'open | part_paid | paid | waived | written_off. Waived and written off are different decisions with different accounting, and neither is a deletion.';
COMMENT ON COLUMN "rent_charges"."is_prorated" IS 'Whether the amount was reduced for a partial period. Flagged because a pro-rated first month is the single most disputed charge in residential letting.';
COMMENT ON COLUMN "rent_charges"."allocation_basis" IS 'floor_area | occupancy | submeter | equal_share, for utility recharges. Records how a building bill was split, which is the first thing a tenant asks.';
COMMENT ON COLUMN "rent_charges"."source_reference" IS 'External document the charge derives from, such as a utility invoice number. Null for rent.';
COMMENT ON COLUMN "rent_charges"."generated_at" IS 'When the charge row was created by the billing run, which is normally well before it falls due.';

CREATE INDEX "idx_charges_lease_due"
ON "rent_charges" ("lease_id", "due_on");
CREATE INDEX "idx_charges_status_due"
ON "rent_charges" ("status", "due_on");

CREATE TABLE IF NOT EXISTS "payments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lease the money arrived against. Payments belong to the tenancy, not to a charge, because a tenant transfers a round number that rarely matches one charge.
	"lease_id" BIGINT NOT NULL,
	-- Which co-tenant paid. Null for a bank transfer that cannot be attributed, which is common and worth representing honestly.
	"paid_by_tenant_id" BIGINT,
	-- Amount received in minor units, always positive. A refund is its own row with method set accordingly.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217 currency received.
	"currency_code" CHAR(3) NOT NULL,
	-- bank_transfer | direct_debit | card | cash | cheque | offset. Offset covers a deposit deduction applied to arrears, which moves no money but settles a charge.
	"method" VARCHAR(24) NOT NULL DEFAULT 'bank_transfer',
	-- Bank or gateway reference. Unique, so a replayed webhook or a re-imported statement line is a no-op rather than a duplicate credit.
	"external_reference" VARCHAR(80) UNIQUE,
	-- Value date at the bank. Distinct from when it was entered, and it is the date that decides whether a payment was late.
	"received_on" DATE NOT NULL,
	-- Portion not yet applied to any charge. A tenant who overpays leaves a credit that must sit somewhere visible rather than vanishing into a balance.
	"unallocated_minor" BIGINT NOT NULL DEFAULT 0,
	-- pending | cleared | bounced | refunded. A bounced payment reverses its allocations and the charges go back to open.
	"status" VARCHAR(24) NOT NULL DEFAULT 'cleared',
	-- Free text, mostly used to record what a tenant said the payment was for when the reference is unhelpful.
	"notes" VARCHAR(300),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payments" IS 'Money in, recorded once. Keeping the payment separate from what it settles is what allows one transfer to clear three charges, a part payment to clear half of one, and an overpayment to sit as an explicit credit.';
COMMENT ON COLUMN "payments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payments"."lease_id" IS 'Lease the money arrived against. Payments belong to the tenancy, not to a charge, because a tenant transfers a round number that rarely matches one charge.';
COMMENT ON COLUMN "payments"."paid_by_tenant_id" IS 'Which co-tenant paid. Null for a bank transfer that cannot be attributed, which is common and worth representing honestly.';
COMMENT ON COLUMN "payments"."amount_minor" IS 'Amount received in minor units, always positive. A refund is its own row with method set accordingly.';
COMMENT ON COLUMN "payments"."currency_code" IS 'ISO 4217 currency received.';
COMMENT ON COLUMN "payments"."method" IS 'bank_transfer | direct_debit | card | cash | cheque | offset. Offset covers a deposit deduction applied to arrears, which moves no money but settles a charge.';
COMMENT ON COLUMN "payments"."external_reference" IS 'Bank or gateway reference. Unique, so a replayed webhook or a re-imported statement line is a no-op rather than a duplicate credit.';
COMMENT ON COLUMN "payments"."received_on" IS 'Value date at the bank. Distinct from when it was entered, and it is the date that decides whether a payment was late.';
COMMENT ON COLUMN "payments"."unallocated_minor" IS 'Portion not yet applied to any charge. A tenant who overpays leaves a credit that must sit somewhere visible rather than vanishing into a balance.';
COMMENT ON COLUMN "payments"."status" IS 'pending | cleared | bounced | refunded. A bounced payment reverses its allocations and the charges go back to open.';
COMMENT ON COLUMN "payments"."notes" IS 'Free text, mostly used to record what a tenant said the payment was for when the reference is unhelpful.';

CREATE INDEX "idx_payments_lease_received"
ON "payments" ("lease_id", "received_on");
CREATE INDEX "idx_payments_status_received"
ON "payments" ("status", "received_on");

CREATE TABLE IF NOT EXISTS "payment_allocations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Payment being applied.
	"payment_id" BIGINT NOT NULL,
	-- Charge being settled.
	"charge_id" BIGINT NOT NULL,
	-- Portion of the payment applied to this charge, in minor units. The sum across a payment can never exceed its amount.
	"amount_minor" BIGINT NOT NULL,
	-- When the application was made, which can be days after the payment cleared if it was allocated manually.
	"allocated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- oldest_first | tenant_directed | manual. Recorded because a tenant who says the money was for this month, not last month, has a legal right to direct it in several jurisdictions.
	"allocation_rule" VARCHAR(24) NOT NULL DEFAULT 'oldest_first',
	-- When the allocation was undone, after a bounced payment or a misapplication. Reversal is dated rather than deleted so the statement still reconciles.
	"reversed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payment_allocations" IS 'The many-to-many between money received and money owed. Without it, arrears reporting degenerates into comparing two totals, which cannot tell you which specific month is unpaid or how long it has been outstanding.';
COMMENT ON COLUMN "payment_allocations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payment_allocations"."payment_id" IS 'Payment being applied.';
COMMENT ON COLUMN "payment_allocations"."charge_id" IS 'Charge being settled.';
COMMENT ON COLUMN "payment_allocations"."amount_minor" IS 'Portion of the payment applied to this charge, in minor units. The sum across a payment can never exceed its amount.';
COMMENT ON COLUMN "payment_allocations"."allocated_at" IS 'When the application was made, which can be days after the payment cleared if it was allocated manually.';
COMMENT ON COLUMN "payment_allocations"."allocation_rule" IS 'oldest_first | tenant_directed | manual. Recorded because a tenant who says the money was for this month, not last month, has a legal right to direct it in several jurisdictions.';
COMMENT ON COLUMN "payment_allocations"."reversed_at" IS 'When the allocation was undone, after a bounced payment or a misapplication. Reversal is dated rather than deleted so the statement still reconciles.';

CREATE UNIQUE INDEX "uq_allocation_payment_charge"
ON "payment_allocations" ("payment_id", "charge_id");
CREATE INDEX "idx_allocations_charge"
ON "payment_allocations" ("charge_id");

CREATE TABLE IF NOT EXISTS "security_deposits" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lease the deposit secures. Unique, because a tenancy holds one deposit; a renewal that increases it transfers rather than creating a second.
	"lease_id" BIGINT NOT NULL UNIQUE,
	-- Amount actually received in minor units, which is not always the contracted figure.
	"amount_held_minor" BIGINT NOT NULL,
	-- ISO 4217 currency held.
	"currency_code" CHAR(3) NOT NULL,
	-- When the money arrived. Statutory protection deadlines run from this date, and missing them carries penalties in several jurisdictions.
	"received_on" DATE NOT NULL,
	-- Protection scheme holding or insuring the money. Null only where the jurisdiction has no scheme.
	"scheme_name" VARCHAR(120),
	-- Certificate or registration number issued by the scheme, the evidence that protection actually happened.
	"scheme_reference" VARCHAR(80),
	-- Date protection was registered. A gap between this and received_on is the compliance failure auditors look for first.
	"protected_on" DATE,
	-- held | partially_returned | returned | in_dispute | forfeited. In dispute is its own state because an adjudicator, not the landlord, decides the outcome.
	"status" VARCHAR(24) NOT NULL DEFAULT 'held',
	-- Total withheld in minor units. Each deduction is normally matched by a repair_recharge charge, so the tenant sees why.
	"deductions_minor" BIGINT NOT NULL DEFAULT 0,
	-- Itemised justification for the deductions. Free text because it has to be readable by an adjudicator, not parsed by a machine.
	"deduction_reason" TEXT,
	-- Amount actually paid back. Held less deductions, and storing both sides means the arithmetic can be shown rather than asserted.
	"returned_minor" BIGINT NOT NULL DEFAULT 0,
	-- When the balance was returned. Null while held, and the age of an unreturned deposit after a tenancy ends is a report worth running.
	"returned_on" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "security_deposits" IS 'The deposit as its own object with its own lifecycle, not two columns on the lease. It is received, protected, partly deducted and returned on a timetable governed by statute rather than by the tenancy dates.';
COMMENT ON COLUMN "security_deposits"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "security_deposits"."lease_id" IS 'Lease the deposit secures. Unique, because a tenancy holds one deposit; a renewal that increases it transfers rather than creating a second.';
COMMENT ON COLUMN "security_deposits"."amount_held_minor" IS 'Amount actually received in minor units, which is not always the contracted figure.';
COMMENT ON COLUMN "security_deposits"."currency_code" IS 'ISO 4217 currency held.';
COMMENT ON COLUMN "security_deposits"."received_on" IS 'When the money arrived. Statutory protection deadlines run from this date, and missing them carries penalties in several jurisdictions.';
COMMENT ON COLUMN "security_deposits"."scheme_name" IS 'Protection scheme holding or insuring the money. Null only where the jurisdiction has no scheme.';
COMMENT ON COLUMN "security_deposits"."scheme_reference" IS 'Certificate or registration number issued by the scheme, the evidence that protection actually happened.';
COMMENT ON COLUMN "security_deposits"."protected_on" IS 'Date protection was registered. A gap between this and received_on is the compliance failure auditors look for first.';
COMMENT ON COLUMN "security_deposits"."status" IS 'held | partially_returned | returned | in_dispute | forfeited. In dispute is its own state because an adjudicator, not the landlord, decides the outcome.';
COMMENT ON COLUMN "security_deposits"."deductions_minor" IS 'Total withheld in minor units. Each deduction is normally matched by a repair_recharge charge, so the tenant sees why.';
COMMENT ON COLUMN "security_deposits"."deduction_reason" IS 'Itemised justification for the deductions. Free text because it has to be readable by an adjudicator, not parsed by a machine.';
COMMENT ON COLUMN "security_deposits"."returned_minor" IS 'Amount actually paid back. Held less deductions, and storing both sides means the arithmetic can be shown rather than asserted.';
COMMENT ON COLUMN "security_deposits"."returned_on" IS 'When the balance was returned. Null while held, and the age of an unreturned deposit after a tenancy ends is a report worth running.';

CREATE TABLE IF NOT EXISTS "vendors" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short code used on work orders and matched against invoices by finance.
	"vendor_code" VARCHAR(24) NOT NULL UNIQUE,
	-- Trading name of the contractor.
	"name" VARCHAR(200) NOT NULL,
	-- plumbing | electrical | heating | roofing | cleaning | pest | general. Dispatch is by trade, so this is the field the assignment logic reads.
	"trade" VARCHAR(40) NOT NULL,
	-- Address work orders are sent to.
	"email" VARCHAR(320),
	-- Number used for urgent dispatch, which is most of them.
	"phone" VARCHAR(32),
	-- Agreed labour rate in minor units, for estimating before a quote arrives.
	"hourly_rate_minor" BIGINT,
	-- ISO 4217 currency of the rate.
	"currency_code" CHAR(3),
	-- Whether they answer out of hours. The most important single attribute at two in the morning.
	"is_emergency_available" BOOLEAN NOT NULL DEFAULT false,
	-- Liability insurance expiry. A vendor with lapsed cover must not be dispatched, which makes this an operational gate rather than a record.
	"insurance_expires_on" DATE,
	-- Average rating from completed work orders, cached for dispatch decisions.
	"rating" NUMERIC(3,2),
	-- Deactivated contractors keep their rows because historical work orders and costs reference them.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "vendors" IS 'The contractors who actually fix things. Dispatch is by trade and availability, which is why both are columns rather than notes in a free-text address book.';
COMMENT ON COLUMN "vendors"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "vendors"."vendor_code" IS 'Short code used on work orders and matched against invoices by finance.';
COMMENT ON COLUMN "vendors"."name" IS 'Trading name of the contractor.';
COMMENT ON COLUMN "vendors"."trade" IS 'plumbing | electrical | heating | roofing | cleaning | pest | general. Dispatch is by trade, so this is the field the assignment logic reads.';
COMMENT ON COLUMN "vendors"."email" IS 'Address work orders are sent to.';
COMMENT ON COLUMN "vendors"."phone" IS 'Number used for urgent dispatch, which is most of them.';
COMMENT ON COLUMN "vendors"."hourly_rate_minor" IS 'Agreed labour rate in minor units, for estimating before a quote arrives.';
COMMENT ON COLUMN "vendors"."currency_code" IS 'ISO 4217 currency of the rate.';
COMMENT ON COLUMN "vendors"."is_emergency_available" IS 'Whether they answer out of hours. The most important single attribute at two in the morning.';
COMMENT ON COLUMN "vendors"."insurance_expires_on" IS 'Liability insurance expiry. A vendor with lapsed cover must not be dispatched, which makes this an operational gate rather than a record.';
COMMENT ON COLUMN "vendors"."rating" IS 'Average rating from completed work orders, cached for dispatch decisions.';
COMMENT ON COLUMN "vendors"."is_active" IS 'Deactivated contractors keep their rows because historical work orders and costs reference them.';

CREATE INDEX "idx_vendors_trade_active"
ON "vendors" ("trade", "is_active");

CREATE TABLE IF NOT EXISTS "maintenance_requests" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Unit concerned. On the unit rather than the lease, because a vacant unit still develops leaks.
	"unit_id" BIGINT NOT NULL,
	-- Lease in force when it was reported. Null when the unit is vacant, and it is what decides whether the tenant or the landlord is recharged.
	"lease_id" BIGINT,
	-- Who reported it. Null for issues found during an inspection or by staff.
	"reported_by_tenant_id" BIGINT,
	-- plumbing | electrical | heating | appliance | structural | pest | other. The routing key for dispatch and the grouping for recurring-fault analysis.
	"category" VARCHAR(40) NOT NULL,
	-- emergency | urgent | normal | low. Emergency means habitability is affected, which starts a statutory response clock in most jurisdictions.
	"priority" VARCHAR(16) NOT NULL DEFAULT 'normal',
	-- What the tenant reported, in their words. Worth keeping verbatim, because the vendor diagnosis frequently disagrees with it.
	"description" TEXT NOT NULL,
	-- How to get in — key location, pets, preferred hours. The single most common reason a scheduled visit fails.
	"access_instructions" VARCHAR(300),
	-- open | triaged | scheduled | in_progress | resolved | closed | rejected. Rejected covers requests that are the tenant responsibility, and recording that is what makes the recharge defensible.
	"status" VARCHAR(24) NOT NULL DEFAULT 'open',
	-- Whether the cost is recharged to the tenant. Set at triage and revisited after diagnosis, because it drives a repair_recharge row in the charge ledger.
	"is_tenant_responsible" BOOLEAN NOT NULL DEFAULT false,
	-- When it came in. The response clock starts here.
	"reported_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the tenant confirmed it was fixed. Null while open, and distinct from the work order completion, because the two disagree more often than anyone would like.
	"resolved_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "maintenance_requests" IS 'The tenant-facing side of maintenance: what was reported and when. Separate from the work order because one report can need three visits from two trades, and because a request can be resolved without any contractor at all.';
COMMENT ON COLUMN "maintenance_requests"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "maintenance_requests"."unit_id" IS 'Unit concerned. On the unit rather than the lease, because a vacant unit still develops leaks.';
COMMENT ON COLUMN "maintenance_requests"."lease_id" IS 'Lease in force when it was reported. Null when the unit is vacant, and it is what decides whether the tenant or the landlord is recharged.';
COMMENT ON COLUMN "maintenance_requests"."reported_by_tenant_id" IS 'Who reported it. Null for issues found during an inspection or by staff.';
COMMENT ON COLUMN "maintenance_requests"."category" IS 'plumbing | electrical | heating | appliance | structural | pest | other. The routing key for dispatch and the grouping for recurring-fault analysis.';
COMMENT ON COLUMN "maintenance_requests"."priority" IS 'emergency | urgent | normal | low. Emergency means habitability is affected, which starts a statutory response clock in most jurisdictions.';
COMMENT ON COLUMN "maintenance_requests"."description" IS 'What the tenant reported, in their words. Worth keeping verbatim, because the vendor diagnosis frequently disagrees with it.';
COMMENT ON COLUMN "maintenance_requests"."access_instructions" IS 'How to get in — key location, pets, preferred hours. The single most common reason a scheduled visit fails.';
COMMENT ON COLUMN "maintenance_requests"."status" IS 'open | triaged | scheduled | in_progress | resolved | closed | rejected. Rejected covers requests that are the tenant responsibility, and recording that is what makes the recharge defensible.';
COMMENT ON COLUMN "maintenance_requests"."is_tenant_responsible" IS 'Whether the cost is recharged to the tenant. Set at triage and revisited after diagnosis, because it drives a repair_recharge row in the charge ledger.';
COMMENT ON COLUMN "maintenance_requests"."reported_at" IS 'When it came in. The response clock starts here.';
COMMENT ON COLUMN "maintenance_requests"."resolved_at" IS 'When the tenant confirmed it was fixed. Null while open, and distinct from the work order completion, because the two disagree more often than anyone would like.';

CREATE INDEX "idx_requests_unit_reported"
ON "maintenance_requests" ("unit_id", "reported_at");
CREATE INDEX "idx_requests_status_priority"
ON "maintenance_requests" ("status", "priority");

CREATE TABLE IF NOT EXISTS "work_orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Request that prompted it. Null for planned preventive work, which has no tenant report behind it.
	"maintenance_request_id" BIGINT,
	-- Unit worked on. Null when the work is on common parts of the building rather than inside a unit.
	"unit_id" BIGINT,
	-- Building the work is at. Always present, since common-area work has no unit to hang from.
	"building_id" BIGINT NOT NULL,
	-- Contractor dispatched. Null while the work order is still being quoted.
	"vendor_id" BIGINT,
	-- repair | preventive | inspection_followup | improvement. Improvements are capital rather than expense, which finance treats entirely differently.
	"work_kind" VARCHAR(24) NOT NULL DEFAULT 'repair',
	-- Instructions given to the contractor, which become the yardstick when the invoice arrives.
	"scope" TEXT,
	-- Quoted amount in minor units. Null for time-and-materials work.
	"quoted_cost_minor" BIGINT,
	-- Invoiced amount. Null until the invoice lands. The gap against the quote is the number that decides whether a vendor keeps getting work.
	"actual_cost_minor" BIGINT,
	-- ISO 4217 currency of the costs.
	"currency_code" CHAR(3),
	-- draft | dispatched | scheduled | in_progress | completed | cancelled | invoiced. Invoiced is after completed because payment approval is a separate step with its own delay.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- Agreed appointment time, which the tenant must be told about.
	"scheduled_for" TIMESTAMPTZ,
	-- When the contractor finished. Null while open.
	"completed_at" TIMESTAMPTZ,
	-- What was actually done and what was found. The input to recurring-fault analysis, and often the justification for a recharge.
	"completion_notes" TEXT,
	-- One to five, recorded at completion. Feeds the cached rating used at dispatch.
	"vendor_rating" SMALLINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "work_orders" IS 'The contractor-facing side: who was sent, what they were asked to do, what it cost. One request can spawn several of these, and preventive work spawns them with no request at all.';
COMMENT ON COLUMN "work_orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "work_orders"."maintenance_request_id" IS 'Request that prompted it. Null for planned preventive work, which has no tenant report behind it.';
COMMENT ON COLUMN "work_orders"."unit_id" IS 'Unit worked on. Null when the work is on common parts of the building rather than inside a unit.';
COMMENT ON COLUMN "work_orders"."building_id" IS 'Building the work is at. Always present, since common-area work has no unit to hang from.';
COMMENT ON COLUMN "work_orders"."vendor_id" IS 'Contractor dispatched. Null while the work order is still being quoted.';
COMMENT ON COLUMN "work_orders"."work_kind" IS 'repair | preventive | inspection_followup | improvement. Improvements are capital rather than expense, which finance treats entirely differently.';
COMMENT ON COLUMN "work_orders"."scope" IS 'Instructions given to the contractor, which become the yardstick when the invoice arrives.';
COMMENT ON COLUMN "work_orders"."quoted_cost_minor" IS 'Quoted amount in minor units. Null for time-and-materials work.';
COMMENT ON COLUMN "work_orders"."actual_cost_minor" IS 'Invoiced amount. Null until the invoice lands. The gap against the quote is the number that decides whether a vendor keeps getting work.';
COMMENT ON COLUMN "work_orders"."currency_code" IS 'ISO 4217 currency of the costs.';
COMMENT ON COLUMN "work_orders"."status" IS 'draft | dispatched | scheduled | in_progress | completed | cancelled | invoiced. Invoiced is after completed because payment approval is a separate step with its own delay.';
COMMENT ON COLUMN "work_orders"."scheduled_for" IS 'Agreed appointment time, which the tenant must be told about.';
COMMENT ON COLUMN "work_orders"."completed_at" IS 'When the contractor finished. Null while open.';
COMMENT ON COLUMN "work_orders"."completion_notes" IS 'What was actually done and what was found. The input to recurring-fault analysis, and often the justification for a recharge.';
COMMENT ON COLUMN "work_orders"."vendor_rating" IS 'One to five, recorded at completion. Feeds the cached rating used at dispatch.';

CREATE INDEX "idx_work_orders_vendor_status"
ON "work_orders" ("vendor_id", "status");
CREATE INDEX "idx_work_orders_building_scheduled"
ON "work_orders" ("building_id", "scheduled_for");

CREATE TABLE IF NOT EXISTS "inspections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Unit inspected.
	"unit_id" BIGINT NOT NULL,
	-- Lease in force at the time. Null for an inspection of a vacant unit between tenancies.
	"lease_id" BIGINT,
	-- move_in | move_out | periodic | safety | post_repair. Move-in and move-out are the pair that decides a deposit deduction, which is why they are distinct values rather than a date comparison.
	"inspection_kind" VARCHAR(24) NOT NULL,
	-- Planned date, which must respect the statutory notice period for entry.
	"scheduled_for" DATE,
	-- When the tenant was notified. Entering without recorded notice is a breach, so the date is stored rather than assumed.
	"notice_given_on" DATE,
	-- Actual date. Null if it has not happened yet, and a long-overdue scheduled inspection is its own report.
	"performed_on" DATE,
	-- Who carried it out, which may be staff or a third party.
	"inspector_name" VARCHAR(200),
	-- excellent | good | fair | poor. A summary grade, because the room-by-room detail lives in the report document.
	"overall_condition" VARCHAR(16),
	-- Narrative findings. Issues that need work become maintenance requests rather than staying buried here.
	"findings" TEXT,
	-- Object storage key for the signed report with photographs. The photographs are the evidence in a deposit dispute; nothing else in the schema substitutes for them.
	"report_document_key" VARCHAR(500),
	-- When the tenant signed off on the findings. An unacknowledged move-in report is very hard to rely on at move-out.
	"tenant_acknowledged_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "inspections" IS 'Condition, recorded on a date with evidence attached. The move-in and move-out pair is the whole legal basis for withholding any part of a deposit, and neither is reconstructable after the fact.';
COMMENT ON COLUMN "inspections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "inspections"."unit_id" IS 'Unit inspected.';
COMMENT ON COLUMN "inspections"."lease_id" IS 'Lease in force at the time. Null for an inspection of a vacant unit between tenancies.';
COMMENT ON COLUMN "inspections"."inspection_kind" IS 'move_in | move_out | periodic | safety | post_repair. Move-in and move-out are the pair that decides a deposit deduction, which is why they are distinct values rather than a date comparison.';
COMMENT ON COLUMN "inspections"."scheduled_for" IS 'Planned date, which must respect the statutory notice period for entry.';
COMMENT ON COLUMN "inspections"."notice_given_on" IS 'When the tenant was notified. Entering without recorded notice is a breach, so the date is stored rather than assumed.';
COMMENT ON COLUMN "inspections"."performed_on" IS 'Actual date. Null if it has not happened yet, and a long-overdue scheduled inspection is its own report.';
COMMENT ON COLUMN "inspections"."inspector_name" IS 'Who carried it out, which may be staff or a third party.';
COMMENT ON COLUMN "inspections"."overall_condition" IS 'excellent | good | fair | poor. A summary grade, because the room-by-room detail lives in the report document.';
COMMENT ON COLUMN "inspections"."findings" IS 'Narrative findings. Issues that need work become maintenance requests rather than staying buried here.';
COMMENT ON COLUMN "inspections"."report_document_key" IS 'Object storage key for the signed report with photographs. The photographs are the evidence in a deposit dispute; nothing else in the schema substitutes for them.';
COMMENT ON COLUMN "inspections"."tenant_acknowledged_at" IS 'When the tenant signed off on the findings. An unacknowledged move-in report is very hard to rely on at move-out.';

CREATE INDEX "idx_inspections_unit_performed"
ON "inspections" ("unit_id", "performed_on");
CREATE INDEX "idx_inspections_kind_scheduled"
ON "inspections" ("inspection_kind", "scheduled_for");

